CREATE TABLE IF NOT EXISTS pull_requests (review_id TEXT PRIMARY KEY REFERENCES reviews(id), tenant TEXT NOT NULL, installation_id INTEGER NOT NULL, repository TEXT NOT NULL, number INTEGER NOT NULL CHECK(number >= 1), request_key TEXT NOT NULL, trigger TEXT NOT NULL CHECK(trigger IN ('webhook','cli','command')), base_sha TEXT, head_sha TEXT, fork INTEGER NOT NULL DEFAULT 0 CHECK(fork IN (0,1)), author_login TEXT, author_type TEXT CHECK(author_type IS NULL OR author_type IN ('user','bot')), agent_json TEXT, consent INTEGER NOT NULL DEFAULT 0 CHECK(consent IN (0,1)), escalated INTEGER NOT NULL DEFAULT 0 CHECK(escalated IN (0,1)), reset INTEGER NOT NULL DEFAULT 0 CHECK(reset IN (0,1)), prepare_token_hash TEXT, claim TEXT, claimed_until INTEGER, state TEXT NOT NULL CHECK(state IN ('requested','preparing','submitted','not_prepared','failed')), reason TEXT, created_at INTEGER NOT NULL, UNIQUE(tenant,repository,number,request_key));
CREATE INDEX IF NOT EXISTS pull_requests_prepare ON pull_requests(prepare_token_hash);
CREATE INDEX IF NOT EXISTS pull_requests_number ON pull_requests(tenant,repository,number,created_at);
CREATE TABLE IF NOT EXISTS publication_leases (tenant TEXT NOT NULL, lineage_id TEXT NOT NULL, holder TEXT NOT NULL, until INTEGER NOT NULL, published_seq INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(tenant,lineage_id));
ALTER TABLE publications ADD COLUMN body_hash TEXT;
ALTER TABLE publications ADD COLUMN url TEXT
